RSpec.describe Invoices::ReservationDecision do
  # "On a draft, entries absent from the new set are released at commit, and a discarded or
  # destroyed draft sends an empty set. On a non-draft, the boundary sends no removal."
  # A discarded draft still has its lines when the save runs; the named row must ignore them.
  it "releases every entry when a draft is discarded while its lines are still attached" do
    expect(described_class::DISCARDED_DRAFT).to be_frozen

    result = described_class.call(
      status: "draft", discarded: true, destroyed: false,
      held: { entries: [1, 2], disposition: "active" }, lines: [1, 2, 3]
